    self.visit(node.value)
    if self._memo.name_matches(node, *annotated_names):
        if isinstance(node.slice, Tuple):
            self.visit(node.slice.elts[0])
        else:
            self.visit(node.slice)
    else:
        self.generic_visit(node.slice)  # actually need self.visit on slice
    return node
